      "ui.check_your_answer": "Your answer:",
      "ui.glossary_heading": "Glossary",
      "ui.sources_footer": "Generated by the Zivon content factory. Sources are listed in the course index.",
      "ui.untranslated_block_notice": "This section is currently in English only.",
